mkdir -p /tmp/preview && cd /tmp/preview && cat > render.mjs <<'EOF'
import fs from "node:fs";
import { marked } from "marked";

const md = fs.readFileSync(process.argv[2], "utf8");

// Tell `marked` to leave ```mermaid blocks untouched so we can swap them
// for <div class="mermaid"> nodes that the Mermaid runtime can pick up.
marked.use({
  renderer: {
    code(code, lang) {
      if (lang === "mermaid") {
        return `<div class="mermaid">${code.text ?? code}</div>`;
      }
      // marked v12+ passes an object; v4 passes a string. Handle both.
      const text = typeof code === "string" ? code : (code.text ?? "");
      const escaped = text
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      return `<pre><code>${escaped}</code></pre>`;
    },
  },
});

const body = marked.parse(md);

const html = `<!doctype html>
<html><head>
  <meta charset="utf-8" />
  <title>Preview</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
      max-width: 1012px;
      margin: 32px auto;
      padding: 0 24px;
      color: #1f2328;
      line-height: 1.5;
    }
    h1, h2 { border-bottom: 1px solid #d0d7de; padding-bottom: .3em; }
    table { border-collapse: collapse; }
    table th, table td { border: 1px solid #d0d7de; padding: 6px 13px; }
    table th { background: #f6f8fa; }
    pre { background: #f6f8fa; padding: 16px; border-radius: 6px; overflow: auto; }
    code { background: #eaeef2; padding: .2em .4em; border-radius: 4px; font-size: 85%; }
    pre code { background: transparent; padding: 0; font-size: 100%; }
    .mermaid { background: white; padding: 12px 0; }
    blockquote { border-left: .25em solid #d0d7de; color: #57606a; padding: 0 1em; }
  </style>
</head><body>
${body}
<script type="module">
  import mermaid from "https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.esm.min.mjs";
  mermaid.initialize({ startOnLoad: false, theme: "default", securityLevel: "loose", flowchart: { htmlLabels: true } });
  await mermaid.run();
  // Mark ready for the screenshot driver.
  window.__renderDone = true;
  document.title = "ready";
</script>
</body></html>`;

fs.writeFileSync(process.argv[3], html);
console.log("wrote", process.argv[3]);
EOF
npm init -y >/dev/null 2>&1 && npm install --no-audit --no-fund marked@12 2>&1 | tail -3
node render.mjs /home/runner/work/The_Dark_Factory/The_Dark_Factory/docs/workflows.md /tmp/preview/preview.html
ls -la /tmp/preview/preview.html
